import bpy
import random

class ObjectRandomRotationPanel(bpy.types.Panel):
    bl_label = "Random Rotation"
    bl_idname = "PT_RandomRotation"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = 'Tools'

    def draw(self, context):
        layout = self.layout
        layout.operator("object.random_rotation_set", text="Set Random Rotation")

class SetRandomRotationOperator(bpy.types.Operator):
    bl_idname = "object.random_rotation_set"
    bl_label = "Set Random Rotation"

    def execute(self, context):
        obj = context.object
        obj.rotation_euler = (random.uniform(0, 3.14159), random.uniform(0, 3.14159), random.uniform(0, 3.14159))
        return {'FINISHED'}

def register():
    bpy.utils.register_class(ObjectRandomRotationPanel)
    bpy.utils.register_class(SetRandomRotationOperator)

def unregister():
    bpy.utils.unregister_class(ObjectRandomRotationPanel)
    bpy.utils.unregister_class(SetRandomRotationOperator)

if __name__ == "__main__":
    register()
